fixed_edges = [(7,9), (1,3), (0,8), (6,11), (1,6), (3,11), (4,9), (4,11), (6,8), (10,11), (5,11), (1,10), (2,6)]

# Compute degrees
degrees = [0]*12
for u,v in fixed_edges:
    degrees[u] += 1
    degrees[v] += 1

for i, d in enumerate(degrees):
    print(f"Vertex {i}: degree = {d}")

print(f"\nVertices needing more edges:")
for i, d in enumerate(degrees):
    if d < 3:
        print(f"  Vertex {i}: needs {3-d} more")
